import{_ as a,o as t,c as i,a0 as n}from"./chunks/framework.BMIT1c_r.js";const p=JSON.parse('{"title":"5. Cross-Scenario Universal Phenomena: Paper List","description":"","frontmatter":{},"headers":[],"relativePath":"universal-phenomena.md","filePath":"universal-phenomena.md"}'),s={name:"universal-phenomena.md"};function r(o,e,l,m,c,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_5-cross-scenario-universal-phenomena-paper-list" tabindex="-1">5. Cross-Scenario Universal Phenomena: Paper List <a class="header-anchor" href="#_5-cross-scenario-universal-phenomena-paper-list" aria-label="Permalink to &quot;5. Cross-Scenario Universal Phenomena: Paper List&quot;">​</a></h1><blockquote><p>&quot;When many different complex systems exhibit the same universal behavior, it strongly suggests that a description exists that is simpler than any particular model in isolation... behavior shared across many systems should depend primarily on the features common to all such systems.&quot;</p></blockquote><h2 id="a-universal-inductive-biases-architectural-convergences" tabindex="-1">A. Universal Inductive Biases &amp; Architectural Convergences <a class="header-anchor" href="#a-universal-inductive-biases-architectural-convergences" aria-label="Permalink to &quot;A. Universal Inductive Biases &amp; Architectural Convergences&quot;">​</a></h2><p><em>Focuses on how disparate network structures—such as ConvNets vs. Transformers or UNet vs. Vision Transformers—converge to near-identical performance boundaries and pixel-level functional mappings under equal computational resource envelopes.</em></p><ul><li><strong>Dosovitskiy et al. [2020]</strong> — <em>An image is worth 16x16 words: Transformers for image recognition at scale</em></li><li><strong>Liu et al. [2022]</strong> — <em>A convnet for the 2020s</em></li><li><strong>Peebles &amp; Xie [2023]</strong> — <em>Scalable diffusion models with transformers</em></li><li><strong>Bhojanapalli et al. [2021]</strong> — <em>Understanding robustness of visual transformers</em></li><li><strong>Cordonnier et al. [2020]</strong> — <em>On the relationship between self-attention and convolutional layers</em></li></ul><hr><h2 id="b-universal-statistical-structure-latent-in-data" tabindex="-1">B. Universal Statistical Structure Latent in Data <a class="header-anchor" href="#b-universal-statistical-structure-latent-in-data" aria-label="Permalink to &quot;B. Universal Statistical Structure Latent in Data&quot;">​</a></h2><p><em>Focuses on isolating the mathematical commonalities embedded across diverse data modalities—such as multiscale wavelets, Zipfian power laws in text, and compositional semantic hierarchies.</em></p><ul><li><strong>Zipf [1949]</strong> — <em>Human behavior and the principle of least effort: An introduction to human ecology</em></li><li><strong>Mallat [1999]</strong> — <em>A wavelet tour of signal processing: The sparse way</em></li><li><strong>Poggio et al. [2017]</strong> — <em>Why and when can deep-but not shallow-networks avoid the curse of dimensionality: a review</em></li><li><strong>Bietti &amp; Mairal [2019]</strong> — <em>On the inductive bias of deep convolutional networks</em></li><li><strong>Michaud et al. [2023]</strong> — <em>The quantization model of neural scaling</em></li></ul><hr><h2 id="c-the-platonic-representation-hypothesis-alignment" tabindex="-1">C. The Platonic Representation Hypothesis &amp; Alignment <a class="header-anchor" href="#c-the-platonic-representation-hypothesis-alignment" aria-label="Permalink to &quot;C. The Platonic Representation Hypothesis &amp; Alignment&quot;">​</a></h2><p><em>Focuses on investigating why internal neural activation layouts across different weights, objectives (supervised vs. self-supervised), modalities, and even biological brains actively align toward a shared, objective representation of reality.</em></p><ul><li><strong>Huh et al. [2024]</strong> — <em>The platonic representation hypothesis</em></li><li><strong>Kornblith et al. [2019]</strong> — <em>Similarity of neural network representations revisited</em></li><li><strong>Yamins et al. [2014]</strong> — <em>Performance-optimized hierarchical models predict neural responses in higher visual cortex</em></li><li><strong>Radford et al. [2021]</strong> — <em>Learning transferable visual models from natural language supervision</em></li><li><strong>Schrimpf et al. [2021]</strong> — <em>Brain-score: Which artificial neural network is most brain-like?</em></li><li><strong>Raghu et al. [2021]</strong> — <em>Do vision transformers see like convolutional networks?</em></li><li><strong>Chung et al. [2024]</strong> — <em>Neural representation similarity metrics: A foundational guide for understanding universality classes</em></li><li><strong>Bordelon et al. [2024c]</strong> — <em>The geometry of representation alignment in deep networks</em></li></ul>',13)])])}const d=a(s,[["render",r]]);export{p as __pageData,d as default};
